  if (window.top !== window.self || window[KEY]) return;

  const apps = [];
  const query = (selector, root = document) => root.querySelector(selector);
  const readSetting = (key) => {
    try {
      const value = localStorage.getItem(key);
      return key === "zf-auto-invade.locale.v1" && value == null ? "zh-CN" : value;
    } catch { return key === "zf-auto-invade.locale.v1" ? "zh-CN" : null; }
  };
  const previousPixiInit = window.__PIXI_APP_INIT__;
  function onPixiInit(app, version) {
    if (app && !apps.includes(app)) apps.push(app);
    if (typeof previousPixiInit === "function") return previousPixiInit.apply(this, arguments);
  }
  try { window.__PIXI_APP_INIT__ = onPixiInit; } catch { /* DOM translations remain available. */ }

  function gameApp() {
    return apps.find((app) => {
      try { return app.stage && app.canvas?.isConnected && query("#app")?.contains(app.canvas); }
      catch { return false; }
    });
  }

